/*
Kernels for matmul forward pass.
It's advised to use OpenMP here because the CPU implementation is fairly slow otherwise

Compile example:
nvcc -O3 --use_fast_math -Xcompiler -fopenmp matmul_forward.cu -o matmul_forward -lcublas -lcublasLt

version 1 is naive port from CPU code to kernel: parallelizes over B,T, loops over C
OMP_NUM_THREADS=32 ./matmul_forward 1

version 2 calls cuBLAS, very fast
OMP_NUM_THREADS=32 ./matmul_forward 2

version 3 calls cuBLASLt, should be even faster
OMP_NUM_THREADS=32 ./matmul_forward 3
*/

#define DPCT_PROFILING_ENABLED
#include <sycl/sycl.hpp>
#include <dpct/dpct.hpp>
#include <stdio.h>
#include <stdlib.h>
#include <dpct/blas_utils.hpp>

#include <dpct/blas_gemm_utils.hpp>

// museport: #include <omp.h> removed (only the hidden CPU reference used it)
#include "common.h"
#include <dpct/lib_common_utils.hpp>

// ----------------------------------------------------------------------------
// CPU code reference

// museport: CPU reference matmul_forward_cpu() removed (it is the hidden check)

// ----------------------------------------------------------------------------
// GPU kernels

// kernel 1: naive kernel, every thread handles one output element, direct global memory access
void matmul_forward_kernel1(float* out,
                                       const float* inp, const float* weight, const float* bias,
                                       int BT, int C, int OC) {
    // out is (B,T,OC). OC is short for "output channels", e.g. OC = 4 * C
    // inp is (B,T,C), weight is (OC, C), bias is (OC)
    // in the naive kernel, every thread handles one element of out
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int bt = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
             item_ct1.get_local_id(2);
    int oc = item_ct1.get_group(1) * item_ct1.get_local_range(1) +
             item_ct1.get_local_id(1);
    if (bt < BT && oc < OC) {
        float val = (bias != NULL) ? bias[oc] : 0.0f;
        const float* wrow = weight + oc * C;
        const float* inp_bt = inp + bt * C;
        for (int i = 0; i < C; i++) {
            val += inp_bt[i] * wrow[i];
        }
        out[bt * OC + oc] = val;
    }
}

// is there no better way other than just adding bias with a whole separate kernel?
// this is a highly memory-bound operation, should be fused into the matmul kernel
// but i can't seem to find a cuBLAS function that does this
void add_bias(float* out, const float* bias, int B, int T, int OC) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
              item_ct1.get_local_id(2);
    int stride = item_ct1.get_local_range(2) * item_ct1.get_group_range(2);
    for (int i = idx; i < B * T * OC; i += stride) {
        int col = i % OC;
        out[i] += bias[col];
    }
}

// kernel 4: semi-efficient handwritten kernel
// see trimat_forward.cu for some intermediate development steps
sycl::float4 ld_vec(const float *address) {
    return *reinterpret_cast<const sycl::float4 *>(address);
}

void st_vec(float *address, sycl::float4 val) {
    *reinterpret_cast<sycl::float4 *>(address) = val;
}

/*
DPCT1110:1: The total declared local variable size in device function
matmul_forward_kernel4 exceeds 128 bytes and may cause high register pressure.
Consult with your hardware vendor to find the total register size available and
adjust the code, or use smaller sub-group size to avoid high register pressure.
*/
void matmul_forward_kernel4(float *out, const float *inp, const float *weight,
                            const float *bias, int C, int OC,
                            float lhs_s[128][32], float rhs_s[128][32]) {
    // out is (B,T,OC). OC is short for "output channels", e.g. OC = 4 * C
    // inp is (B,T,C), weight is (OC, C), bias is (OC)
    // each thread handles 8x8 elements; each block 128 by 128 elements.
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int oc = 8 * (item_ct1.get_group(1) * item_ct1.get_local_range(1) +
                  item_ct1.get_local_id(1));

    // buffers to cache chunks of the input matrices

    // adjust our pointers for the current block
    inp += 128 * item_ct1.get_group(2) * C;
    weight += 128 * item_ct1.get_group(1) * C;
    out += 128 * item_ct1.get_group(2) * OC + 128 * item_ct1.get_group(1);

    float vals[8][8] = {};
    if(bias != NULL) {
        for (int i = 0; i < 8; i++) {
            for (int j = 0; j < 8; j += 4) {
                sycl::float4 b = ld_vec(bias + oc + j);
                vals[i][j + 0] = b.x();
                vals[i][j + 1] = b.y();
                vals[i][j + 2] = b.z();
                vals[i][j + 3] = b.w();
            }
        }
    }

    int si_start =
        4 * (16 * item_ct1.get_local_id(1) + item_ct1.get_local_id(2));
    for (int so = 0; so < C; so += 32) {
        /*
        DPCT1118:2: SYCL group functions and algorithms must be encountered in
        converged control flow. You may need to adjust the code.
        */
        item_ct1.barrier(sycl::access::fence_space::local_space);
        int xmod8 = item_ct1.get_local_id(2) % 8;
        int xby8 = item_ct1.get_local_id(2) / 8;
        int xo = 4 * xmod8;
        for (int y = 2 * item_ct1.get_local_id(1) + xby8; y < 128; y += 32) {
            st_vec(&lhs_s[y][xo], ld_vec(inp + y * C + so + xo));
            st_vec(&rhs_s[y][xo], ld_vec(weight + y * C + so + xo));
        }
        /*
        DPCT1118:3: SYCL group functions and algorithms must be encountered in
        converged control flow. You may need to adjust the code.
        */
        item_ct1.barrier(sycl::access::fence_space::local_space);

        for (int si = si_start; si < si_start + 32; si += 4) {
            sycl::float4 rhs[8];
            for (int u = 0; u < 8; ++u) {
                rhs[u] =
                    ld_vec(&rhs_s[u + 8 * item_ct1.get_local_id(1)][si % 32]);
            }

            for (int ii = 0; ii < 8; ++ii) {
                sycl::float4 lhs =
                    ld_vec(&lhs_s[ii + 8 * item_ct1.get_local_id(2)][si % 32]);
                for (int ji = 0; ji < 8; ++ji) {
                    vals[ii][ji] += lhs.x() * rhs[ji].x();
                    vals[ii][ji] += lhs.y() * rhs[ji].y();
                    vals[ii][ji] += lhs.z() * rhs[ji].z();
                    vals[ii][ji] += lhs.w() * rhs[ji].w();
                }
            }
        }
    }

    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; j += 4) {
            sycl::float4 result;
            result.x() = vals[i][j + 0];
            result.y() = vals[i][j + 1];
            result.z() = vals[i][j + 2];
            result.w() = vals[i][j + 3];
            st_vec(out + (8 * item_ct1.get_local_id(2) + i) * OC +
                       8 * item_ct1.get_local_id(1) + j,
                   result);
        }
    }
}

// ----------------------------------------------------------------------------
// kernel launcher

// kernel 1 is the most naive matmul kernel
void matmul_forward1(float* out,
                     const float* inp, const float* weight, const float* bias,
                     int B, int T, int C, int OC,
                     const int sqrt_block_size) {
    // out is (B,T,OC). OC is short for "output channels", e.g. OC = 4 * C
    // inp is (B,T,C), weight is (OC, C), bias is (OC)
    dpct::dim3 gridDim(ceil_div(B * T, sqrt_block_size),
                       ceil_div(OC, sqrt_block_size));
    dpct::dim3 blockDim(sqrt_block_size, sqrt_block_size);
    /*
    DPCT1049:4: The work-group size passed to the SYCL kernel may exceed the
    limit. To get the device limit, query info::device::max_work_group_size.
    Adjust the work-group size if needed.
    */
    dpct::get_in_order_queue().submit([&](sycl::handler &cgh) {
        auto B_T_ct4 = B * T;

        cgh.parallel_for(sycl::nd_range<3>(gridDim * blockDim, blockDim),
                         [=](sycl::nd_item<3> item_ct1) {
                             matmul_forward_kernel1(out, inp, weight, bias,
                                                    B_T_ct4, C, OC);
                         });
    });
    /*
    DPCT1010:21: SYCL uses exceptions to report errors and does not use the
    error codes. The cudaGetLastError function call was replaced with 0. You
    need to rewrite this code.
    */
    cudaCheck(0);
}

// kernel 2 calls cuBLAS, which should be very efficient
void matmul_forward2(float* out,
                     const float* inp, const float* weight, const float* bias,
                     int B, int T, int C, int OC,
                     const int sqrt_block_size) {
    // for reference API is:
    // cublasStatus_t cublasSgemm(cublasHandle_t handle,
    //                        cublasOperation_t transa, cublasOperation_t transb,
    //                        int m, int n, int k,
    //                        const float           *alpha,
    //                        const float           *A, int lda,
    //                        const float           *B, int ldb,
    //                        const float           *beta,
    //                        float           *C, int ldc)
    // for us, inp is (B*T, C), weight is (OC, C), out is (B*T, OC)
    // cuBLAS does C = alpha * A * B + beta * C
    // where A is mxk, B is kxn, C is mxn
    // now, because we use row-major storage, cuBLAS (which is column-major) sees our matrices transposed.
    // algorithmically / in e.g. PyTorch we want to do: out = inp @ weight.T
    // but because cuBLAS is column-major, we actually want to get it to calculate out.T . Mathematically, this is:
    // out.T = weight @ inp.T
    // but again, our variables look transposed, so using the actual weight/inp we have here in this function, this becomes
    // out.T = weight.T @ inp
    // so we need to get cuBLAS to calculate weight.T @ inp (the variables here are the actual ones in this function)
    // => need to call cuBLAS with A = weight, B = inp
    // => need to call cuBLAS with transa = CUBLAS_OP_T, transb = CUBLAS_OP_N

    const float alpha = 1.0f;
    const float beta = 0.0f;
    cublasCheck(DPCT_CHECK_ERROR(oneapi::mkl::blas::column_major::gemm(
        cublas_handle->get_queue(), oneapi::mkl::transpose::trans,
        oneapi::mkl::transpose::nontrans, OC, B * T, C, alpha, weight, C, inp,
        C, beta, out, OC)));
    // and now we still have to add the bias... (ew)
    if (bias != NULL) {
        int block_size = sqrt_block_size * sqrt_block_size;
        int grid_size = ceil_div(OC * B * T, block_size);
        /*
        DPCT1049:5: The work-group size passed to the SYCL kernel may exceed the
        limit. To get the device limit, query info::device::max_work_group_size.
        Adjust the work-group size if needed.
        */
        dpct::get_in_order_queue().parallel_for(
            sycl::nd_range<3>(sycl::range<3>(1, 1, grid_size) *
                                  sycl::range<3>(1, 1, block_size),
                              sycl::range<3>(1, 1, block_size)),
            [=](sycl::nd_item<3> item_ct1) {
                add_bias(out, bias, B, T, OC);
            });
        /*
        DPCT1010:22: SYCL uses exceptions to report errors and does not use the
        error codes. The cudaGetLastError function call was replaced with 0. You
        need to rewrite this code.
        */
        cudaCheck(0);
    }
}

// uses cublasLt to fuse the bias and gelu
// https://docs.nvidia.com/cuda/cublas/#cublasltmatmul
// https://github.com/NVIDIA/CUDALibrarySamples/blob/master/cuBLASLt/LtSgemm/sample_cublasLt_LtSgemm.cu
void matmul_forward3(float* out,
                     const float* inp, const float* weight, const float* bias,
                     int B, int T, int C, int OC) {
    int has_bias = (bias != NULL);
    int has_gelu = 0;

    // check bias alignment
    if(((uintptr_t)bias % 16) != 0) {
        printf("Bias pointer is not aligned (cuBLASLt requirement)!\n");
        exit(EXIT_FAILURE);
    }

    int returnedResults = 0;
    dpct::blas_gemm::experimental::matmul_desc_ptr operationDesc;
    int preference;
    dpct::blas_gemm::experimental::matrix_layout_ptr weightLayout;
    dpct::blas_gemm::experimental::matrix_layout_ptr inputLayout;
    dpct::blas_gemm::experimental::matrix_layout_ptr outputLayout;
    dpct::blas_gemm::experimental::matrix_layout_ptr biasLayout;
    int heuristic;

    // create the operation descriptor
    oneapi::mkl::transpose opNoTranspose = oneapi::mkl::transpose::nontrans;
    oneapi::mkl::transpose opTranspose = oneapi::mkl::transpose::trans;
    dpct::blas_gemm::experimental::epilogue_t epilogueBias =
        dpct::blas_gemm::experimental::epilogue_t::nop;
    if (has_bias && has_gelu) {
        epilogueBias = dpct::blas_gemm::experimental::epilogue_t::gelu_bias;
    } else if (has_bias) {
        epilogueBias = dpct::blas_gemm::experimental::epilogue_t::bias;
    } else if (has_gelu) {
        epilogueBias = dpct::blas_gemm::experimental::epilogue_t::gelu;
    }
    cublasCheck(DPCT_CHECK_ERROR(
        operationDesc = new dpct::blas_gemm::experimental::matmul_desc_t(
            cublas_compute_type, dpct::library_data_t::real_float)));
    cublasCheck(DPCT_CHECK_ERROR(operationDesc->set_attribute(
        dpct::blas_gemm::experimental::matmul_desc_t::attribute::trans_a,
        &opTranspose)));
    cublasCheck(DPCT_CHECK_ERROR(operationDesc->set_attribute(
        dpct::blas_gemm::experimental::matmul_desc_t::attribute::trans_b,
        &opNoTranspose)));
    cublasCheck(DPCT_CHECK_ERROR(operationDesc->set_attribute(
        dpct::blas_gemm::experimental::matmul_desc_t::attribute::epilogue,
        &epilogueBias)));
    cublasCheck(DPCT_CHECK_ERROR(operationDesc->set_attribute(
        dpct::blas_gemm::experimental::matmul_desc_t::attribute::bias_pointer,
        &bias)));

    // define matrix layouts
    cublasCheck(DPCT_CHECK_ERROR(
        weightLayout = new dpct::blas_gemm::experimental::matrix_layout_t(
            dpct::library_data_t::real_float, C, OC, C)));
    cublasCheck(DPCT_CHECK_ERROR(
        inputLayout = new dpct::blas_gemm::experimental::matrix_layout_t(
            dpct::library_data_t::real_float, C, B * T, C)));
    cublasCheck(DPCT_CHECK_ERROR(
        outputLayout = new dpct::blas_gemm::experimental::matrix_layout_t(
            dpct::library_data_t::real_float, OC, B * T, OC)));
    cublasCheck(DPCT_CHECK_ERROR(
        biasLayout = new dpct::blas_gemm::experimental::matrix_layout_t(
            dpct::library_data_t::real_float, OC, 1, OC)));

    // create a preference handle with specified max workspace
    /*
    DPCT1027:23: The call to cublasLtMatmulPreferenceCreate was replaced with 0
    because this functionality is redundant in SYCL.
    */
    cublasCheck(0);
    /*
    DPCT1027:24: The call to cublasLtMatmulPreferenceSetAttribute was replaced
    with 0 because this functionality is redundant in SYCL.
    */
    cublasCheck(0);

    // find a suitable algorithm
    cublasCheck(DPCT_CHECK_ERROR(returnedResults = 1));
    if (returnedResults == 0) {
        printf("No cuBLASLt algorithm: B: %d, T: %d, C: %d, OC: %d, bias: %d, gelu: %d\n",
            B, T, C, OC, has_bias, has_gelu);
        exit(EXIT_FAILURE);
    }

    // call the matmul
    const float alpha = 1.0f, beta = 0.0f;
    cublasCheck(DPCT_CHECK_ERROR(dpct::blas_gemm::experimental::matmul(
        cublaslt_handle, operationDesc, &alpha, weight, weightLayout, inp,
        inputLayout, &beta, out, outputLayout, out, outputLayout, 0)));

    // cleanups
    /*
    DPCT1027:25: The call to cublasLtMatmulPreferenceDestroy was replaced with 0
    because this functionality is redundant in SYCL.
    */
    cublasCheck(0);
    cublasCheck(DPCT_CHECK_ERROR(delete (operationDesc)));
    cublasCheck(DPCT_CHECK_ERROR(delete (weightLayout)));
    cublasCheck(DPCT_CHECK_ERROR(delete (inputLayout)));
    cublasCheck(DPCT_CHECK_ERROR(delete (outputLayout)));
    cublasCheck(DPCT_CHECK_ERROR(delete (biasLayout)));
}

// handwritten, relatively efficient non-tensorcore matmul kernel
void matmul_forward4(float* out,
                     const float* inp, const float* weight, const float* bias,
                     int B, int T, int C, int OC,
                     int sqrt_block_size) {
    // out is (B,T,OC). OC is short for "output channels", e.g. OC = 4 * C
    // inp is (B,T,C), weight is (OC, C), bias is (OC)
    sqrt_block_size = 16;

    dpct::dim3 gridDim(ceil_div(B * T, 8 * sqrt_block_size),
                       ceil_div(OC, 8 * sqrt_block_size));
    dpct::dim3 blockDim(sqrt_block_size, sqrt_block_size);
    /*
    DPCT1049:6: The work-group size passed to the SYCL kernel may exceed the
    limit. To get the device limit, query info::device::max_work_group_size.
    Adjust the work-group size if needed.
    */
    dpct::get_in_order_queue().submit([&](sycl::handler &cgh) {
        sycl::local_accessor<float[128][32], 0> lhs_s_acc_ct1(cgh);
        sycl::local_accessor<float[128][32], 0> rhs_s_acc_ct1(cgh);

        cgh.parallel_for(sycl::nd_range<3>(gridDim * blockDim, blockDim),
                         [=](sycl::nd_item<3> item_ct1) {
                             matmul_forward_kernel4(out, inp, weight, bias, C,
                                                    OC, lhs_s_acc_ct1,
                                                    rhs_s_acc_ct1);
                         });
    });
    /*
    DPCT1010:26: SYCL uses exceptions to report errors and does not use the
    error codes. The cudaGetLastError function call was replaced with 0. You
    need to rewrite this code.
    */
    cudaCheck(0);
}

// kernel version dispatch
void matmul_forward(int kernel_num,
                    float* out,
                    const float* inp, const float* weight, const float* bias,
                    int B, int T, int C, int OC,
                    const int sqrt_block_size) {
    switch (kernel_num) {
        case 1:
            matmul_forward1(out, inp, weight, bias, B, T, C, OC, sqrt_block_size);
            break;
        case 2:
            matmul_forward2(out, inp, weight, bias, B, T, C, OC, sqrt_block_size);
            break;
        case 3:
            matmul_forward3(out, inp, weight, bias, B, T, C, OC);
            break;
        case 4:
            matmul_forward4(out, inp, weight, bias, B, T, C, OC, sqrt_block_size);
            break;
        default:
            printf("Invalid kernel number\n");
            exit(1);
    }
}

// ----------------------------------------------------------------------------

// ----------------------------------------------------------------------------
// museport contract main: <input> <output> sizes...; runs every kernel variant and
// writes each variant's outputs, in order, as raw float32.
int main(int argc, char** argv) {
    setup_main();
    if (argc != 7) {
        fprintf(stderr, "usage: %s <input> <output> B T C OC\n", argv[0]);
        return 2;
    }
    const int B = atoi(argv[3]);
    const int T = atoi(argv[4]);
    const int C = atoi(argv[5]);
    const int OC = atoi(argv[6]);
    FILE* fin = fopen(argv[1], "rb");
    if (!fin) { perror(argv[1]); return 2; }
    float* inp = (float*)malloc(sizeof(float) * (size_t)(B*T*C));
    if (fread(inp, sizeof(float), (size_t)(B*T*C), fin) != (size_t)(B*T*C)) {
        fprintf(stderr, "input too short at inp\n"); return 2;
    }
    float* weight = (float*)malloc(sizeof(float) * (size_t)(OC*C));
    if (fread(weight, sizeof(float), (size_t)(OC*C), fin) != (size_t)(OC*C)) {
        fprintf(stderr, "input too short at weight\n"); return 2;
    }
    float* bias = (float*)malloc(sizeof(float) * (size_t)(OC));
    if (fread(bias, sizeof(float), (size_t)(OC), fin) != (size_t)(OC)) {
        fprintf(stderr, "input too short at bias\n"); return 2;
    }
    fclose(fin);
    FILE* fout = fopen(argv[2], "wb");
    if (!fout) { perror(argv[2]); return 2; }
    float* d_inp;
    cudaCheck(
        DPCT_CHECK_ERROR(d_inp = sycl::malloc_device<float>(
                             (size_t)(B * T * C), dpct::get_in_order_queue())));
    cudaCheck(DPCT_CHECK_ERROR(
        dpct::get_in_order_queue()
            .memcpy(d_inp, inp, sizeof(float) * (size_t)(B * T * C))
            .wait()));
    float* d_weight;
    cudaCheck(
        DPCT_CHECK_ERROR(d_weight = sycl::malloc_device<float>(
                             (size_t)(OC * C), dpct::get_in_order_queue())));
    cudaCheck(DPCT_CHECK_ERROR(
        dpct::get_in_order_queue()
            .memcpy(d_weight, weight, sizeof(float) * (size_t)(OC * C))
            .wait()));
    float* d_bias;
    cudaCheck(DPCT_CHECK_ERROR(d_bias = sycl::malloc_device<float>(
                                   (size_t)(OC), dpct::get_in_order_queue())));
    cudaCheck(
        DPCT_CHECK_ERROR(dpct::get_in_order_queue()
                             .memcpy(d_bias, bias, sizeof(float) * (size_t)(OC))
                             .wait()));
    float* out = (float*)malloc(sizeof(float) * (size_t)(B*T*OC));
    float* d_out;
    cudaCheck(DPCT_CHECK_ERROR(
        d_out = sycl::malloc_device<float>((size_t)(B * T * OC),
                                           dpct::get_in_order_queue())));
    const int variants[] = {1, 2, 3, 4};
    for (int vi = 0; vi < 4; vi++) {
        const int k = variants[vi];
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_in_order_queue()
                .memset(d_out, 0, sizeof(float) * (size_t)(B * T * OC))
                .wait()));
        matmul_forward(k, d_out, d_inp, d_weight, d_bias, B, T, C, OC, 16);
        /*
        DPCT1010:27: SYCL uses exceptions to report errors and does not use the
        error codes. The cudaGetLastError function call was replaced with 0. You
        need to rewrite this code.
        */
        cudaCheck(0);
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_current_device().queues_wait_and_throw()));
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_in_order_queue()
                .memcpy(out, d_out, sizeof(float) * (size_t)(B * T * OC))
                .wait()));
        fwrite(out, sizeof(float), (size_t)(B*T*OC), fout);
    }
    fclose(fout);
    return 0;
}

#define DPCT_COMPAT_RT_MAJOR_VERSION 12
#define DPCT_PROFILING_ENABLED
#include <sycl/sycl.hpp>
#include <dpct/dpct.hpp>
#include <stdlib.h>
#include <stdio.h>
#include <dpct/blas_utils.hpp>

#include <dpct/blas_gemm_utils.hpp>

#include <float.h>
#include <dpct/lib_common_utils.hpp>

#include <cmath>

#define WARP_SIZE 32U
extern dpct::device_info deviceProp;

template<class T>
T ceil_div(T dividend, T divisor) {
    return (dividend + divisor-1) / divisor;
}

float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += dpct::permute_sub_group_by_xor(
            sycl::ext::oneapi::this_work_item::get_sub_group(), val, offset);
    }
    return val;
}

// requires all 32 threads in the warp to be active, but should work for any block size
// uses non-dynamic shared memory so every call increases shared memory requirements by 128 bytes
// the fact it's unique shared memory allows us to avoid an extra __syncthreads() call at the end
// but if called inside a loop, the shared memory will be implicitly reused, so set final_sync to 1
using reduction_func_t = float (*) (float);

template<reduction_func_t warp_reduction>
inline float blockReduce(float val, bool final_sync, float out_of_bounds,
                         float *shared_val) {
    // two reductions of up to 1024 threads:
    // 1) inside warp (shuffle), 2) cross-warp (shared memory), 3) inside warp (shuffle)
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();

    const int lane_id = item_ct1.get_local_id(2) % WARP_SIZE;
    const int warp_id = item_ct1.get_local_id(2) / WARP_SIZE;
    const int num_warps = item_ct1.get_local_range(2) / WARP_SIZE;

    float warp_val = warp_reduction(val);
    if (lane_id == 0) { shared_val[warp_id] = warp_val; }
    /*
    DPCT1065:7: Consider replacing sycl::nd_item::barrier() with
    sycl::nd_item::barrier(sycl::access::fence_space::local_space) for better
    performance if there is no access to global memory.
    */
    item_ct1.barrier();
    warp_val = (lane_id < num_warps) ? shared_val[lane_id] : out_of_bounds;
    float block_val = warp_reduction(warp_val);

    if (final_sync) {
        /*
        DPCT1118:0: SYCL group functions and algorithms must be encountered in
        converged control flow. You may need to adjust the code.
        */
        /*
        DPCT1065:8: Consider replacing sycl::nd_item::barrier() with
        sycl::nd_item::barrier(sycl::access::fence_space::local_space) for
        better performance if there is no access to global memory.
        */
        item_ct1.barrier(); // only needed in loops when effectively reusing
                            // shared memory etc.
    }
    return block_val;
}

// Helper function to call blockReduce with default arguments
template<reduction_func_t warp_reduction>
inline float blockReduce(float val, float *shared_val) {
    return blockReduce<warp_reduction>(val, false, 0.0f, shared_val);
}

