               float *dst_r = rhs_ptr + static_cast<std::size_t>(y) * 32 + xo;
               dst_r[0] = src_r[0];
               dst_r[1] = src_r[1];
               dst_r[2] = src_r[2];
               dst_r[3] = src_r[3];
